def is_prime(n: int) -> bool:
    """Return whether n is prime."""
    # Handle trivial cases
    if n < 2:
        return False
    # 2 is the only even prime
    if n == 2:
        return True
    # Even numbers greater than 2 are not prime
    if n % 2 == 0:
        return False
    # Check odd divisors up to sqrt(n)
    limit = int(n ** 0.5) + 1
    for d in range(3, limit, 2):
        if n % d == 0:
            return False
    return True
